 ('TLS actual input profile','main/ota_transport.cpp','static_assert(MBEDTLS_SSL_IN_CONTENT_LEN == tk::kOtaTlsInContentB,','static_assert(true,'),
 ('TLS actual output profile','main/ota_transport.cpp','static_assert(MBEDTLS_SSL_OUT_CONTENT_LEN == tk::kOtaTlsOutContentB,','static_assert(true,'),
 ('TLS target binding enabled','main/ota_transport.cpp','#if defined(ESP_PLATFORM)','#if 0'),
 ('TLS hostname','main/ota_transport.cpp','cfg.common_name = hostname.data();','cfg.common_name = nullptr;'),
 ('TLS certificate','main/ota_transport.cpp','cfg.skip_common_name = false;','cfg.skip_common_name = true;'),
 ('cleanup flags CAS','main/ota_transport.cpp','const auto next = (observed & ~kPhaseMask) | kClose |','const auto next = kClose |'),
 ('checkpoint INTERNAL sample','main/ota_update.cpp','heap_caps_get_info(&info, MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT);','heap_caps_get_info(&info, MALLOC_CAP_8BIT);'),
 ('checkpoint guard identity','main/ota_update.cpp','guard_sample ? guard_largest : info.largest_free_block','info.largest_free_block'),
 ('checkpoint complete headers','main/ota_coordinator.cpp','headers_before < 200 && framing_->status() >= 200','headers_before < 200'),
 ('checkpoint before cleanup publication','main/ota_transport.cpp','memory_checkpoint(cleanup_ok ? "tls_destroyed" : "tls_destroy_failed",\n                              j.generation, j.started_ms);','(void)cleanup_ok;'),
 ('header byte cap','main/ota_http.cpp','header_bytes_ >= limits_.headers_bytes','false'),
 ('body bound','main/ota_http.cpp','n > s.limits_.body_bytes - std::min(s.body_bytes_,s.limits_.body_bytes)','false'),
 ('image version equality','main/ota_writer.cpp','available != expected','false'),
 ('downgrade/channel','main/ota_writer.cpp','!tk::is_ota_update_available(available,current,s.policy_.target_pr,s.policy_.channel)','false'),
