 ('public signature verification','main/ota_writer.cpp','const auto result = esp_ota_end(h);','const auto result = ESP_OK;'),
 ('verified boot selector','main/ota_writer.cpp','esp_ota_set_boot_partition(s.partition_)','ESP_OK'),
 ('deadline before raw end','main/ota_coordinator.cpp','if (!begun_ || !alive())','if (!begun_)'),
